  'settings.connections.type': 'Тип',
  'settings.connections.typeHint': '„Няма“ и „Директно“ значат различни неща. „Няма“ е бездеен ред: не сочи никаква връзка и никога не се използва, така че живее само докато не го попълниш докрай. „Директно“ е истински избор: трафикът излиза през собствената връзка на тази машина и заобикаля всяко прокси за хостовете, изброени по-долу. Така изключваш NAS от прокси за цялото приложение. Ред, чийто филтър съвпада с хоста, бие ред без филтър, затова директен ред с филтър винаги печели пред прокси, което хваща всичко.',
