  'settings.rules.var.source': 'N-тият сегмент от пътя в URL адреса на изходната страница, броено от 1: при https://site.org/tv/s01/list.html 1 е tv, а 2 е s01. JDownloader разбира под този таг друго; (i) до „Вмъкни променлива“ обяснява разликата.',
  'settings.rules.var.match': 'Прихващаща група N от шаблона „съвпада с шаблон“ на това правило върху полето FIELD. Това е <jd:source:N> на JDownloader, под име, което казва кой шаблон чете. Правило без съвпадащ шаблон върху това поле се отхвърля при запис, вместо мълчаливо да произведе папка на име <jd:match:url:1>.',
