  'settings.rules.sourceDivergence': 'Копираш шаблон от конфигурация на JDownloader? Тук <jd:source:N> значи друго: сегмент от пътя на изходния URL, а не прихващаща група. Значението от JD се пише <jd:match:FIELD:N>. Двете съвпадат достатъчно често, за да е опасно, затова копиран шаблон си струва да го пробваш на сухо по-долу, преди да го запазиш.',

