  'settings.reconnect.method.script': 'Скрипт',
  'settings.reconnect.offState': 'Повторното свързване е изключено. Нищо не иска нов адрес от рутера, а ограничението на хостера остава за обичайната пауза между опитите.',

  'settings.reconnect.command': 'Програма',
  'settings.reconnect.commandHint': 'Пълният път до програмата, която ще се пусне. Тя тръгва направо, а не през обвивка, така че канал, пренасочване или две команди една след друга са работа на начина „Скрипт“. %%router%%, %%username%%, %%password%% и %%ip%% се заместват преди пускането.',
  'settings.reconnect.args': 'Аргументи',
  'settings.reconnect.argsHint': 'По един на ред, за да остане аргумент с интервал един аргумент. Тук се заместват същите четири променливи.',

  'settings.reconnect.upnpState': 'Нищо друго не е нужно. Шлюзът се открива с питане по мрежата, затова това е методът, който работи, без да знаеш нищо за рутера.',
  'settings.reconnect.upnpLocation': 'URL с описанието на шлюза',
  'settings.reconnect.upnpLocationHint': 'По избор и обикновено празно. Попълвай го само там, където групово адресираното търсене е филтрирано, а самият шлюз се достига чудесно, което самото откриване никога не може да поправи.',

  'settings.reconnect.interpreter': 'Интерпретатор',
  'settings.reconnect.interpreterHint': 'Програмата, на която се подава скриптът, с пълен път: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Аргументи на интерпретатора',
  'settings.reconnect.interpreterArgsHint': 'По един на ред, слагат се преди файла на скрипта. Обикновено празно.',
  'settings.reconnect.script': 'Скрипт',
  'settings.reconnect.scriptHint': 'Записва се в личен временен файл, а на интерпретатора се подава пътят му, така че нищо оттук никога не попада в кавички на команден ред. Променливите се заместват, преди файлът да бъде записан, което значи, че парола, написана в това поле, стига до онзи файл: с %%password%% тя си остава в полето за парола.',

  'settings.reconnect.router': 'Адрес на рутера',
  'settings.reconnect.routerHint': 'Рутерът в собствената ти мрежа, без схема: 192.168.1.1, а не http://192.168.1.1/. Точно в това се превръща %%router%%. Това не е публичният адрес и двата никога не бива да се разменят: заявка за вход, насочена към публичния, изпраща паролата на рутера ти в интернет.',
  'settings.reconnect.routerFind': 'Намери моя рутер',
