  'settings.reconnect.password': 'Парола за рутера',
  'settings.reconnect.passwordStored': 'запазена и никога не се връща тук',
  'settings.reconnect.passwordHint': 'Запазена парола никога не се връща на тази страница и затова полето е празно: остави го празно и запазената се пази. Напиши нова, за да я замениш. За да я махнеш напълно, напиши нещо и после пак изчисти полето.',

  'settings.reconnect.requests': 'Заявки',
  'settings.reconnect.requestsHint': 'Възпроизвеждат се по ред и изпълнението спира при първата, на която рутерът не отговори. Това е начинът LiveHeader от JDownloader: обикновено вход, а после рестарт или прекъсване. Всяко поле приема променливите.',
