  'settings.reconnect.requestHeaders': 'Заглавки',
  'settings.reconnect.requestHeadersHint': 'По една на ред, като Име: стойност. Заглавката Host се зачита и наистина стига до кабела, а точно това е нужно на фърмуер на рутер, който сервира административната си страница като виртуален хост.',
  'settings.reconnect.requestBody': 'Тяло',
  'settings.reconnect.requestBodyHint': 'Изпраща се както е написано. Тяло без собствен тип съдържание тръгва като изпращане на формуляр, а записаният вход в рутер е точно това.',

  'settings.reconnect.import': 'Внасяне на скрипт',
  'settings.reconnect.importLabel': 'Скрипт LiveHeader или curl',
  'settings.reconnect.importHint': 'Постави скрипт за повторно свързване от JDownloader, заедно с маркерите. Променливите му се превеждат на входа, а %%%routerip%%% става адресът на рутера, а не публичният, защото тук това са две различни неща.',
  'settings.reconnect.importRead': 'Прочети скрипта',
