  'settings.reconnect.importLine': 'Ред {n}',
  'settings.reconnect.importBlocked': 'От скрипт с отхвърлен ред в него не се взема нищо. Половин скрипт за рутер е вход без рестарт, а това излиза наяве чак след дни, като адрес, който никога не се сменя.',
  'settings.reconnect.importFailed': 'Скриптът не можа да се прочете: {reason}',

  'settings.reconnect.checkTitle': 'Проверка на адреса',
  'settings.reconnect.checkUrl': 'URL за проверка на IP',
  'settings.reconnect.checkUrlHint': 'Зарежда се преди изпълнението на метода и още веднъж след него; изпълнението се брои за готово, щом адресът, който показва, се промени. Няма стойност по подразбиране: мениджър за изтегляне, който хостваш сам, не бива да започва да съобщава адреса ти на услуга, която никога не си избирал. Показаното трябва да е адресът, който вижда интернет, защото страница, която връща адреса в собствената ти мрежа, не може да различи повторно свързване от изпълнение, което не е направило нищо.',
  'settings.reconnect.checkPresets': 'Известни услуги',
  'settings.reconnect.checkPresetsHint': 'Пряк път за онези без предпочитания, а не стойност по подразбиране: никоя от тях не се избира вместо теб и всяка страница, която показва публичния ти адрес, върши същата работа.',
  'settings.reconnect.interval': 'Секунди между проверките (от 1 до 60)',
  'settings.reconnect.intervalHint': 'Колко да се чака между два погледа към адреса за проверка, след като начинът е изпълнен. Има долна граница, защото цикъл без нея превръща услугата за проверка в мишена.',
  'settings.reconnect.timeout': 'Секунди за проверяване (от 5 до 900)',
  'settings.reconnect.timeoutHint': 'How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.',
  'settings.reconnect.clamped': 'Запазено като {n}.',

  'settings.reconnect.runTitle': 'Пускане сега',
