  'settings.reconnect.reason.noScript': 'Методът „скрипт“ няма скрипт',
  'settings.reconnect.reason.noCheckURL': 'Липсва URL за проверка на IP',
  'settings.reconnect.reason.unknownMethod': 'Непознат метод „{method}“',
  'settings.reconnect.reason.noRouter': 'Скриптът използва %%{var}%%, но не е зададен адрес на рутера',
  'settings.reconnect.runUsesSaved': 'Изпълнява се записаното, а не това на екрана. Първо запазете.',
  'settings.reconnect.policy': 'Кога това става само',
  'settings.reconnect.policyHint': 'Автоматичните повторни свързвания се пускат само на едно място и тази страница не е то. Едно тръгва, когато самото ядро за изтегляне поиска нов опит след изчакване, а така хостерът казва, че ограничението виси на този адрес. То никога не работи, докато опашката е спряна, защото рестартът на рутера къса изтеглянията, които още вървят. Никога не работи и докато повторното свързване не е настроено докрай. Работи само по едно наведнъж: втора заявка чака присъдата на първата, вместо да се бие с нея за рутера. А ако адресът не се промени, нищо не се избързва и обичайната пауза между опитите си върви.',

  'shell.bar': 'Опашка и лента на състоянието',
  'shell.scope': 'Управлява',
  'shell.scopeHint': 'Страницата отдолу показва този сроден екземпляр, затова и лентата сочи към него. Сродният екземпляр има собствена опашка и собствено ограничение на скоростта, затова всичко, което този екземпляр не може да предаде нататък, се показва като недостъпно, вместо да се приложи на тази машина.',

