  'settings.chunks': 'Връзки на изтегляне (0 = автоматично)',
  'settings.chunksHint': 'Колко връзки отваря едно изтегляне, когато не важи нищо по-конкретно. Правило или отделно изтегляне може да посочи собствено число и бие това. Хостър, който търпи по-малко, пак получава по-малко: ограничението на хостъра може само да свали числото, никога да го вдигне. При 0 решава приложението. Повече от шепа връзки не носят нищо при хостър, който ограничава за файл, и са сигурен начин един акаунт да бъде отбелязан.',
  'task.chunks': 'Връзки (0 = общата настройка)',
  'task.chunksHint': 'Колко връзки отваря точно това изтегляне. Бие общата настройка и всяко правило, което я е задало, но никога хостъра: хостър, който търпи по-малко, пак получава по-малко. При 0 изключението отпада и числото пак се решава другаде.',
  'columns.connection': 'Връзка',

  'props.title': 'Свойства',
  'props.mixed': 'Няколко стойности',
  'props.mixedHint': 'Тези редове не съвпадат, затова полето е празно. Ако не го докоснете, нищо не се променя; напишете в него и всеки избран ред получава написаното.',
  'props.name': 'Име',
  'props.nameHint': 'Едно име на файл, никога път: име с / или \\ се отхвърля. Завършено изтегляне се преименува и на диска, за да не могат списъкът и папката да се разминават. Текущо изтегляне запазва файла, който бекендът му е отворил, и получава новото име, когато приключи. Незапочнато изтегляне го получава веднага. Името принадлежи на един файл, затова това поле се предлага само за един ред.',
  'props.comment': 'Бележка',
  'props.commentHint': 'Твоята собствена бележка за тази връзка. Запазва се и се показва в списъка; нищо в приложението не се води по нея.',
  'props.priority': 'Приоритет',
  'props.priorityHint': 'По-високият тръгва пръв. Пренарежда това, което още чака; вече течащо изтегляне не се връща в опашката.',
  'props.autoExtract': 'Разархивиране на архиви',
  'props.autoExtractHint': 'Дали архивът се разопакова след като изтеглянето приключи. „Наследяване“ оставя решението на страницата с настройки за архиви, което не е същото като „изключено“. Ключът се чете в момента на разопаковането, така че включването му сега разопакова и нещо, което е приключило по-рано.',
  'props.inherit': 'Наследяване',
  'props.on': 'Включено',
  'props.off': 'Изключено',

