  'settings.scripts.trigger': 'Стартира при',
  'settings.scripts.triggerHint':
    'Какво стартира този скрипт. При „Ръчно“ се изпълнява само когато го поискаш: от „Пробно изпълнение“ по-долу или от елемента „Изпълни скрипт“ в контекстното меню на списъка с изтегляния.',
  'settings.scripts.trigger.manual': 'Ръчно (само по заявка)',
