  'settings.scripts.starter': '// Този скрипт се изпълнява при събитието, избрано по-горе.\n// log(...) записва ред в „Изход“, а notify(message) изпраща известие.\n// trigger и queue ги има винаги; task, pkg, extraction, reconnect,\n// account и captcha само когато събитието ги носи.\n',
