  'settings.access.relay.title': 'Реле на проекта',
  'settings.access.relay.body': 'Релето е посредник, който прави всичките ти инстанции достъпни извън домашната мрежа, тоест отвсякъде. Това реле проектът предоставя безплатно.',
  'settings.access.relay.use': 'Използвай релето на проекта',
  'settings.access.relay.leadProject': 'Работи без настройване. Всичко, което си казват екземплярите ти, е шифровано, а ключът е само у теб.',
  'settings.access.relay.seesButton': 'Какво вижда?',
  'settings.access.relay.seesTip': 'Невидимо за релето: твоите връзки, изтегляния, файлове и токен за достъп.\n\nВидимо за релето: IP адресите на инстанциите ти и кога изпращат нещо.\n\nТова не може да се скрие с криптиране. Ако те смущава, пусни собствено реле.',
  'settings.access.relay.seesAddress': 'Релето на проекта работи на {address}.',
  'settings.access.relay.none': 'Без реле',
  'settings.access.relay.noneHint': 'Няма активно реле. В една и съща мрежа, тоест у дома, инстанциите пак се намират сами. През различни мрежи не се достигат, така че отдалечен достъп няма.',
  'settings.access.relay.own': 'Собствено реле',
  'settings.access.relay.project': 'Реле на проекта',
  'settings.access.relay.whichHint': 'Минава през {address}',
  'settings.access.relay.savedProject': 'Релето на проекта е активно',
  'settings.access.relay.savedOwn': 'Твоето реле е активно',
  'settings.access.relay.savedOff': 'Релето е изключено',
  'settings.access.ownRelay.title': 'Твоето собствено реле',
  'settings.access.ownRelay.body': 'Пусни собствено реле вместо това на проекта.',
  'settings.access.ownRelay.use': 'Използвай моето реле',
  'settings.access.ownRelay.lead': 'Два пътя: този екземпляр поема релето, или въвеждаш адрес.',
  'settings.access.ownRelay.serveLabel': 'Използвай тази инстанция като реле',
  'settings.access.ownRelay.serveHint': 'Работи само ако тази инстанция е достъпна отвън, например през Nginx Proxy Manager и собствен домейн.',
  'settings.access.ownRelay.serveClients': 'В момента свързани: {count}.',
  'settings.access.ownRelay.addressLabel': 'Адрес',
  'settings.access.ownRelay.addressPlaceholder': 'напр. https://relay.mydomain.tld',
  'settings.access.ownRelay.save': 'Запази',
  'settings.access.ownRelay.everyInstance': 'Този адрес важи само за този екземпляр. Въведи го на всеки.',
  'settings.access.ownRelay.containerLabel': 'Като собствен контейнер',
  'settings.access.ownRelay.containerHint': 'Ако нито една от инстанциите ти не е достъпна отвън, релето трябва да живее другаде, на твоя сървър или на малък VPS. Инсталирай контейнера от Unraid Community Applications или с командата по-долу.\n\nКонтейнерът не иска настройка: пусни го, въведи адреса му горе, готово. Не пази нищо, така че няма какво да архивираш.',
  'settings.access.tokens.title': 'API токени',
  'settings.access.tokens.intro':
    'Именувани удостоверения за скрипт, разширение на браузър или телефон. Всеки може да бъде отменен поотделно, без да се променя споделената парола, която използват останалите клиенти.',
  'settings.access.tokens.empty': 'Все още не е издаден токен.',
