  'settings.access.tokens.secretWarning':
    'Този токен се показва само този единствен път. Съхранява се на тази инстанция като еднопосочен хеш - ако се изгуби, няма начин да бъде прочетен отново, само да бъде отменен и създаден нов.',
  'settings.access.tokens.copy': 'Копирай',
  'settings.access.tokens.copied': 'Копирано',
