  'settings.access.identity.title': 'Идентичност на тази инстанция',
  'settings.access.identity.nameLabel': 'Име',
  'settings.access.identity.namePlaceholder': 'напр. Домашен сървър',
  'settings.access.identity.nameHint': 'Предлага се първо при сдвояване и в QR кода по-долу, вместо името, което операционната система или средата на контейнера случайно дава на тази машина. По избор: остави празно, за да продължиш да използваш това име.',
  'settings.access.identity.domainsLabel': 'Известни домейни',
  'settings.access.identity.domainsHint': 'Всеки домейн се запомня автоматично при първата заявка, която пристигне през него, и остава в списъка тук, дори когато по-късните заявки идват през LAN IP адреса. Добави домейн ръчно, ако вече е настроен, но през него още не е дошла заявка. По един пълен адрес на ред, напр. https://kl.example.com.',
  'settings.access.cardTitle': 'Свързване на инстанции и отдалечен достъп',
  'settings.access.phrase.body': 'Една фраза свързва всички KnightLoader, които поддържаш. Създай я тук и после я постави в другите си инстанции. Не ти трябват акаунт или вход и няма нищо за настройване.',
  'settings.access.phrase.noPasswordWarning': 'Тази инстанция няма парола. Фразата достига всяка инстанция, която свържете с нея, така че всеки, който я прочете тук, стига до всички, не само до тази. По-добре първо задайте парола по-горе.',
  'settings.access.phrase.activate': 'Създай фраза',
  'settings.access.phrase.howStep1': 'На тази инстанция натисни „{button}“. Появяват се дванадесет думи.',
  'settings.access.phrase.howStep2': 'Отвори KnightLoader на другото устройство, влез в същата страница, натисни „{button}“ и въведи дванадесетте думи.',
  'settings.access.phrase.howStep3': 'Готово! Всяка инстанция вече се появява при другата под „Инстанции“ и можеш да управляваш всяка от всяка. При включено реле инстанциите ти са достъпни извън твоята мрежа.',
  'settings.access.phrase.howWhat': 'Думите са тайна, не адрес. Всяка инстанция изчислява от тях два ключа: един за намиране на останалите и един за криптиране.\n\nЗа да се намерят, всяка инстанция сама звъни на една и съща точка на среща в интернет. Който покаже същия ключ, бива свързан. Затова нито една твоя инстанция не трябва да е достъпна отвън.\n\nТочката на среща не може да чете. Тя никога не вижда думите ти, а всичко, което минава през нея, е криптирано с втория ключ.',
  'settings.access.phrase.statusDisconnected': 'Не е свързано',
  'settings.access.phrase.statusHintProject': 'Свързано с релето на проекта. Отдалеченият достъп е настроен.',
  'settings.access.phrase.statusHintOwn': 'Свързано със собственото ти реле. Отдалеченият достъп е настроен.',
  'settings.access.phrase.statusHintOff': 'Няма активно реле. Инстанциите ти са достъпни само в локалната мрежа.',
  'settings.access.phrase.statusHintLost': 'Няма връзка с релето. KnightLoader продължава да опитва. Дотогава инстанциите се намират само в локалната мрежа.',
  'settings.access.phrase.statusConnected': 'Свързано',
  'settings.access.phrase.howButton': 'Как работи това?',
