  'settings.browsertools.serverTitle': 'На сървър',
  'settings.browsertools.serverHint': 'На сървър KnightLoader продължава да изтегля, докато този компютър е изключен. Инсталирай го от Unraid Community Applications, пусни го като Docker контейнер или го компилирай от изходния код.',
