  'settings.resolvers.moduleUnavailable': 'Модулът не е наличен',
  'settings.resolvers.moduleUnavailableHint': 'Всичко по-долу пак се запазва и влиза в сила в момента, в който yt-dlp стане наличен. Нищо, което редактираш сега, не се губи.',
  'settings.resolvers.about': 'Настройки за бекенда yt-dlp, който изтегля от медийните и стрийминг сайтовете, поддържани от самия yt-dlp. Коя услуга изобщо обработва дадена връзка (yt-dlp, debrid акаунт или бекендът JDownloader), решава редът на приоритет на страницата „Акаунти“. Тук задаваш какво прави yt-dlp, след като връзката е насочена към него.',
