  'settings.resolvers.qualityHint': 'Кой селектор -f се използва при стартиране на yt-dlp. „Най-доброто налично“ е собствената стойност по подразбиране на yt-dlp и това, което всяко изтегляне е използвало преди тази настройка да съществува.',
