  'settings.torrents.portTitle': 'Порт и пренасочване',
  'settings.torrents.port': 'Порт',
  'settings.torrents.portHint': 'Портът, на който тази инстанция слуша за връзки от роя. 0 оставя торент машината да избере сама.',
  'settings.torrents.portRestartHint': 'Машината създава торент клиента си само веднъж, затова нов порт влиза в сила след рестарт на тази инстанция. Да помолиш рутера да го пренасочи работи веднага, независимо дали някой торент вече слуша на него.',
  'settings.torrents.portMapHint': 'Иска от рутера да пренасочи горния порт към тази машина през UPnP, за да могат пиъри зад друг рутер все пак да го достигнат. Не всеки рутер поддържа това, а някои приемат заявката, без тя реално да проработи.',
  'settings.torrents.portMapButton': 'Опит за UPnP пренасочване',
  'settings.torrents.portMapping': 'Изчаква отговор от рутера…',
  'settings.torrents.portMapNeedsPort': 'Задай порт по-горе, преди да го пренасочиш. При 0 рутерът няма към какво да пренасочва.',
  'settings.torrents.portMapConfirmed': 'Потвърдено: портът {port} е пренасочен и е проверен като достъпен.',
  'settings.torrents.portMapUnconfirmed': 'Рутерът прие заявката, но не можа да се потвърди, че пренасочването работи. Някои рутери приемат заявката тихо, без да я приложат. Опитай проверка на свързаността извън мрежата.',
  'settings.torrents.portMapFailed': 'Портът не можа да бъде пренасочен: {error}',
  'settings.torrents.portMapUnavailable': 'Тази версия все още не предлага пренасочване на портове.',
  'settings.torrents.networkTitle': 'Откриване на пиъри',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Намира пиъри без никакъв тракер, като използва други BitTorrent клиенти като разпределен указател.',
  'settings.torrents.pex': 'Обмен на пиъри (PEX)',
  'settings.torrents.pexHint': 'Обменя познати пиъри с вече свързаните, за да се открие по-бързо рой с малко пиъри.',
  'settings.torrents.privateNote': 'Частен торент изключва и двете автоматично, щом метаданните му станат известни, независимо от настройката тук: веднага при качен .torrent файл или щом собствените метаданни на magnet връзка пристигнат от роя. Повечето частни тракери банват акаунти, които използват което и да е от двете.',
  'container.noJD': 'шифрован е и само бекенд на JDownloader може да го отвори. Няма настроен такъв: задай в KL_JD JDownloader, до който тази инстанция стига, и рестартирай инстанцията.',
  'container.jdOff': 'шифрован е и само бекендът на JDownloader може да го отвори. „Бекенд JDownloader“ е изключен на страницата „Модули“.',
  'torrent.staging': 'Добавяне…',
