  'settings.torrents.notApplied': 'Тази компилация още не прилага две от настройките по-долу. Лимитът на качване се запазва и проверява, но машината не може да го приложи към текущо изтегляне. DHT и PEX също не стигат до обикновен торент: той сийдва с двете включени, каквото и да е зададено тук. При частен торент е различно, както обяснява (i) при „Откриване на пиъри“.',
  'onboarding.step': 'Стъпка {n} от {total}',
  'onboarding.skip': 'Пропусни',
  'onboarding.back': 'Назад',
  'onboarding.next': 'Напред',
  'onboarding.finish': 'Готово',
  'onboarding.welcome.title': 'Добре дошъл в KnightLoader',
  'onboarding.welcome.body': 'KnightLoader е мениджър за изтегляне, който хостваш сам. Постави или пусни връзка и подходящият бекенд я изтегля: вграденият механизъм за обикновени връзки към файлове, yt-dlp за медийни страници, debrid услуга за хостъри, за които вече плащаш, или headless JDownloader за всичко останало. Тази кратка обиколка показва единствената настройка, която си струва да провериш, преди да започнеш.',
  'onboarding.welcome.langLabel': 'Език на интерфейса',
  'onboarding.folder.title': 'Къде трябва да отиват файловете?',
  'onboarding.folder.body': 'Това е папката, в която се записват завършените изтегляния. Въведи път или разгледай сървъра, за да избереш. Можеш да я смениш по всяко време от страницата с настройки „Общи“.',
  'onboarding.accounts.title': 'Премиум хостове, когато поискаш',
  'onboarding.accounts.body': 'Опашката работи и без никакъв акаунт. Когато искаш пълна скорост при хостър или debrid услуга, за които вече плащаш, добави данните за вход в „Акаунти“. Нищо от това не е нужно да настройваш сега.',
  'onboarding.accounts.link': 'Отвори „Акаунти“',
  'onboarding.finished.title': 'Готово е',
  'onboarding.finished.body': 'С това обиколката приключва. Страницата „Помощ“ в настройките съдържа пълно ръководство за всичко останало, което тази версия прави, а повечето контроли носят собствено обяснение зад иконка (i).',

