  'settings.feeds.remembered': 'Запомнени записи: {n}',
  'settings.feeds.rememberedHint': 'Колко записа разпознава този абонамент отново, за да не бъдат добавени втори път, докато емисията още ги предлага. Най-много 500 на абонамент. Първи отпадат най-старите, а запис, който още стои в емисията, никога не е сред тях.',
  'settings.feeds.test': 'Пробвай',
