  'settings.feeds.testFailed': 'Тази емисия не можа да бъде прочетена',

  'settings.headerProfiles.title': 'Профили със заглавки',
  'settings.headerProfiles.hint': 'Някои страници дават файла само на браузър, който е влязъл в акаунт, или само когато заявката идва от някоя от собствените им страници. Профилът запазва заглавките за точно една страница, шифровани по същия начин като ключовете ти за акаунти, и KnightLoader ги изпраща при всяко изтегляне от тази страница.',
  'settings.headerProfiles.empty': 'Още няма профили със заглавки.',
