  'settings.headerProfiles.headerValue': 'Стойност',
  'settings.headerProfiles.valueStored': 'Запазена',
  'settings.headerProfiles.valueStoredHint': 'Стойността остава на тази инстанция и никога не се връща към тази страница. Остави полето както е, за да я запазиш, или напиши нова стойност, за да я замениш.',
