  'settings.headerProfiles.delete': 'Изтрий профила',
  'settings.headerProfiles.deleteConfirm': 'Да се изтрие ли профилът {id}? Заглавките в него изчезват, а изтеглянията от {origin} отново тръгват без тях.',

  'settings.rules.action.category': 'Категория',
  'settings.rules.action.categoryHint': 'Подрежда съвпадналите връзки в едно от чекмеджетата от списъка „Категории“ по-надолу на тази страница, което носи със себе си собствена папка, място в опашката, ключ за разархивиране и правило за файл, който вече е там. Оставено без промяна, никое правило няма мнение по въпроса и връзката остава неподредена. Ако това правило посочва и папка за изтегляния, печели тя, а чекмеджето доставя всичко останало. Да посочите изтрито чекмедже се отказва при запис, защото правило, което сочи към чекмедже, което го няма, не прави абсолютно нищо при всяка съвпаднала връзка, без нито едно съобщение.',
  'settings.rules.action.categoryNone': 'Още няма категории. Създай първо една в „Категории“ по-надолу на тази страница, иначе това правило би подреждало връзки в чекмедже, което не съществува.',
