  'detail.doing': 'В момента прави',
  'detail.gaveUp': 'Без нов опит',
  'detail.gaveUpHint': 'Тук е спряно нарочно, а не защото опитите са свършили: captcha, пълен диск или правило, което казва „никога“ за този хостър. Вдигането на броя повторения не променя нищо тук. Самото обозначение не се записва в базата данни, така че след рестарт го няма, макар причината за него да остава.',
  'detail.rules': 'Правила, които оформиха това',
  'detail.rulesHint': 'Правилата, които са се задействали върху тази връзка при подготвянето ѝ, в реда, в който са се задействали. Пазят се по име, така че преименувано оттогава правило вече не се намира, а правило, което никога не е имало име, се пази с мястото, което е заемало тогава. Щракването върху някое от тях го отваря в редактора на правила.',
  'detail.openRule': 'Отвори в редактора на правила',
  'detail.noRules': 'Нито едно правило не е докоснало тази връзка.',
  'detail.player': 'Възпроизвеждане',
  'detail.play': 'Пусни тук',
  'detail.playHint': 'Пуска файла направо от тази инстанция, без да го тегли втори път. Докато не натиснеш Пусни, не се взема нищо, а файлът си остава където е.',
  'detail.playPartial': 'Това изтегляне не е завършено. Пуска се само частта, която вече е на диска, прескачане отвъд нея не става, а някои файлове не пускат нищо, докато последният байт не пристигне.',
  'detail.playUnsupported': 'Този браузър не може да пусне този файл. Вместо това го отвори или запази от менюто с десния бутон.',
  'detail.playRemote': 'Тук се пускат само файлове на тази инстанция. Друга инстанция подава файловете си наведнъж и без прескачане, а с това плейърът не може да работи.',
  'detail.playNotLocal': 'Това изтегляне е свалено от JDownloader, така че файлът лежи на диска на онзи процес, а не на този тук.',
  'detail.playNoFile': 'На диска още няма какво да се пусне.',
  'detail.playRefused': 'Сървърът не дава този файл: {reason}',
  'detail.playFailed': 'Възпроизвеждането спря: {reason}',
  'detail.playClose': 'Затвори плейъра',

  'settings.rules.notFound': 'Тук няма правило на име „{name}“. Било е преименувано или изтрито, откакто е добавена връзката, която го назовава.',

  'notifications.title': 'Известия',
  'notifications.titleHint': 'Реши за всяко събитие дали да се показва като балонче в приложението, като известие от операционната ти система, или изобщо да не се показва. Системното известие те достига само докато има отворен раздел на KnightLoader, а тихият режим по-долу важи и отгоре на това.',
  'notifications.channel.app': 'В приложението',
  'notifications.channel.system': 'Системно известие',
  'notifications.channel.silent': 'Не показвай нищо',
  'notifications.event.downloadDone': 'Изтеглянето приключи',
  'notifications.event.downloadDoneHint': 'Всяко изтегляне, което стигне до края, се обажда. Двеста файла в опашката значат двеста такива известия, така че помисли добре, преди да ги пратиш към системата.',
  'notifications.event.downloadFailed': 'Изтеглянето се провали',
  'notifications.event.downloadFailedHint': 'Изтегляне, което се е отказало. Тихият режим никога не скрива това.',
  'notifications.event.extractionDone': 'Разархивирането приключи',
  'notifications.event.extractionDoneHint': 'Архив, който е разархивиран докрай. Досега това не се съобщаваше никъде, затова започва на „Не показвай нищо“.',
  'notifications.event.extractionFailed': 'Разархивирането се провали',
  'notifications.event.extractionFailedHint': 'Архив, който е спрял, без да завърши. Обикновено липсва паролата, а файловете си остават на място, докато не се погрижиш.',
  'notifications.event.captchaWaiting': 'Чака captcha',
  'notifications.event.captchaWaitingHint': 'Прозорецът с captcha се отваря в този раздел така или иначе. Започва на „Не показвай нищо“, защото този прозорец вече е самото съобщение, докато гледаш към него. Сложи го на системно известие и captcha във фонов раздел те достига, преди хостърът да изхвърли сесията.',
  'notifications.event.captchaFailed': 'Captcha се провали',
  'notifications.event.captchaFailedHint': 'Никой не е отговорил навреме или отговорът не е стигнал. Изтеглянето зад нея си остава на място.',
  'notifications.event.captchaResolved': 'Captcha, решена другаде',
  'notifications.event.captchaResolvedHint': 'Някой в друг браузър или автоматична решаваща услуга е отговорил и прозорецът се е затворил сам.',
  'notifications.systemUnavailable': 'Системните известия ги няма тук: браузърът ти ги предлага само по HTTPS или на localhost. Всичко на тази карта пак се показва в приложението.',
  'notifications.systemBlocked': 'Браузърът ти блокира известията за този адрес. Редовете, сложени на „Системно известие“, се показват в приложението, докато не ги разрешиш отново в настройките за този сайт в браузъра си.',
  'notifications.systemNotGranted': 'Браузърът не даде разрешение, затова това събитие остава в приложението. Избери „Системно известие“ още веднъж, за да бъде поискано пак.',
  'notifications.test': 'Изпрати тест',
  'notifications.testBody': 'Ето как изглежда известие от KnightLoader.',
