  'settings.search.placeholder': 'Търсене във всички настройки…',
  'settings.search.hint': 'Претърсва всички раздели на настройките: имената на разделите, заглавията на картите, надписа до всеки контрол и обясненията зад (i). Избереш ли резултат, разделът се отваря и редът се отбелязва. Не търси в стойностите, които си задал: за тях има поле на страницата „Разширени“.',
