  'views.label': 'Запазени изгледи',
  'views.save': 'Запази този изглед',
  'views.saveHint': 'Изгледът е търсенето и филтрите, които си задал в момента, запазени под име, което сам избираш. Колоните и подреждането не са част от него, те се помнят отделно.',
  'views.saveTitle': 'Дай име на този изглед',
  'views.nameLabel': 'Име',
