  'settings.selftest.status.fail': 'Счупено',
  'settings.selftest.status.skipped': 'Не е настроено',
  'settings.selftest.status.unknown': 'Не се установява',
  'settings.selftest.jd': 'Бекенд JDownloader',
  'settings.selftest.jd.ok': 'Достъпен, ревизия {version}.',
  'settings.selftest.jd.provisioningOff': 'Автоматичното разгръщане на бекенда е изключено и няма зададен адрес, така че няма към какво да се свърже.',
  'settings.selftest.jd.missing': 'Няма адрес на бекенда. Шифрованите DLC и връзките към контейнери се отхвърлят.',
  'settings.selftest.jd.missingAdvice': 'Тази компилация обикновено стартира собствен JDownloader без графичен интерфейс при пускането си и сама попълва KL_JD. Това, че е празно, значи, че този старт се е провалил. Потърси „JD provisioning failed“ в дневника по-долу или насочи KL_JD към собствен JDownloader.',
  'settings.selftest.jd.unreachable': '{address} не отговори.',
  'settings.selftest.jd.unreachableAdvice': 'Адресът е запазен, но на него нищо не слуша. Провери дали бекендът работи и дали портът му 3128 е достъпен отвътре на този контейнер, а не само от хоста.',
  'settings.selftest.jd.noVersion': 'Отговаря, но не казва коя ревизия е.',
  'settings.selftest.ytdlp': 'yt-dlp',
  'settings.selftest.ytdlp.ok': '{version}, на {days} дни.',
  'settings.selftest.ytdlp.aging': '{version} е на {days} дни.',
  'settings.selftest.ytdlp.old': '{version} е на {days} дни. Големите видео сайтове обикновено го чупят в рамките на седмици.',
  'settings.selftest.ytdlp.oldAdvice': 'В контейнера yt-dlp идва от пакета на Alpine, който е бил актуален при построяването на образа, и никога не се обновява сам. Издърпай по-нов образ или монтирай собствен yt-dlp в контейнера и насочи KL_YTDLP към него.',
  'settings.selftest.ytdlp.missing': 'Не е намерен, затова медийните страници се провалят със собствената грешка на хостъра.',
  'settings.selftest.ytdlp.missingAdvice': 'Насочи KL_YTDLP към изпълнимия файл или сложи yt-dlp в PATH. Търси се веднъж при пускането, така че инсталиран сега се използва чак след рестарт.',
  'settings.selftest.ytdlp.undated': '{version} не прилича на дата, така че възрастта му не може да бъде преценена.',
  'settings.selftest.folders': 'Папка за изтегляния и работна папка',
  'settings.selftest.folders.allOk': 'Всяка проверена папка я има и в нея може да се пише.',
  'settings.selftest.folders.someBad': 'При поне една папка има какво да се погледне.',
