  'settings.downloads.keepAwakeHint': 'Докато върви изтегляне и докато след това се проверява, разархивира, мести или подава на програма за събития, компютърът не заспива. Изтегляне, което чака следващ опит, също се брои. Екранът пак може да се изключи. Щом всичко това приключи, компютърът отново заспива както обикновено.',
  'settings.transfer.incompleteEventPrograms': 'командните редове на програмите за събития',
  'settings.eventPrograms.argsHint': 'По един на ред. Всеки ред стига до програмата като един аргумент с попълнени заместители и никоя обвивка не го чете: име на файл, което съдържа $( ) или ;, пристига точно с тези знаци. Файл .bat или .cmd получава всеки аргумент в кавички, така че там го чети като "%~1". Ако програмата е обвивка, използвай вместо заместителите променливите на средата, в двойни кавички, например "$KL_FILE", за да не може обвивката да прочете име на файл като команда.',
  'settings.eventPrograms.envHint': 'Всяко изпълнение ги получава, празни там, където събитието няма нищо за тях. KL_FILE е файлът на изтеглянето, а KL_FOLDER е папката, в която той се намира. За завършен пакет KL_FOLDER е папката, в която са отишли повечето му файлове; за разархивиран архив това е папката, в която е разархивиран. Неуспешно разархивиране също стартира програмата, с KL_EXTRACT_OK, зададено на false. Ако използваш работна папка, завършено изтегляне или пакет изчаква файловете му да бъдат преместени от нея, до 15 минути. Собствените KL_ настройки на тази инстанция, включително ключовете за услуги, никога не се предават.',
  'settings.eventPrograms.timeoutHint': 'Колко дълго може да трае едно изпълнение, преди да бъде спряно, между 5 и 3600 секунди. Всичко, което програмата е стартирала, се спира заедно с нея.',
