  'settings.torrents.includeFiles': 'Само тези файлове',
  'settings.torrents.includeFilesHint': 'По един регулярен израз на ред, сравнява се с пътя на файла вътре в торента, както „съвпада с шаблон“ в правило на Packagizer. Файлът трябва да съвпадне с някой от тях, за да бъде изтеглен. Малките и главните букви имат значение; започни шаблона с (?i), за да ги пренебрегне.',
