  'collector.filtered.heldSummary': 'Задържани връзки: {n}',
  'collector.filtered.heldInfo': 'Връзки, които правило на филтъра за връзки е отказало, и торенти, които се обявяват към забранен тракер. Държат се тук, а не в списъка отгоре, за да не изглежда колекторът пълен с боклук при работещ филтър. Нищо не е изгубено. „Възстанови“ връща връзката и я пуска покрай правилото или забраната, която я е спряла, за случаите, когато тя се е оказала твърде широка. „Изчисти“ я изтрива. Така или иначе не е изтеглен нито един файл.',
  'collector.filtered.toastHeldBack': 'Добавени връзки: {n}; задържани: {held}',
  'collector.filtered.toastAllHeldBack': 'Нищо не е добавено, задържани връзки: {held}',
  'settings.torrents.filesHint': 'Избира кои файлове от торент се изтеглят, когато никой не ги е избрал ръчно. При magnet връзка това става, щом пристигне списъкът ѝ с файлове. Файл .torrent отваря списъка си с файлове с вече отметнат този избор и той важи, ако добавиш торента, без да го променяш. Каквото сам отметнеш или размаркираш, винаги печели. Ако не остане нищо, се изтеглят всички файлове. Категория може вместо това да има собствен избор на файлове.',
  'settings.torrents.extraTrackersHint': 'По един адрес на тракер на ред, добавят се към торентите, за да намират повече пиъри. Файл .torrent, отбелязан като частен, никога не ги получава. Magnet връзка казва дали е частна едва когато пристигне списъкът ѝ с файлове, а дотогава тракерите вече са добавени, затова не получава такива и magnet, чийто собствен адрес на тракер съдържа passkey. Частен тракер, който те разпознава по IP адреса, а не по passkey, не може да бъде открит по този начин: остави това поле празно, ако получаваш magnet връзки от такъв тракер.',
  'settings.torrents.bannedTrackersHint': 'По едно име на хост или адрес на тракер на ред; поддомейните му също се броят. Торент, който се обявява към някой от тях, не се добавя: колекторът го задържа с причината, както връзка, която филтърът за връзки отказва. Ако го възстановиш там, той минава покрай реда, който го е спрял, но не и покрай ред, който добавиш по-късно. Забранен тракер също никога не се добавя като допълнителен тракер.',
  'detail.heldBecause': 'Задържано поради',
  'settings.categories.torrentFiles': 'Избор на файлове от торент',
  'settings.categories.torrentFilesHint': 'Кои файлове от торент, подреден тук, се изтеглят, когато никой не ги е отметнал ръчно. „Наследяване“ използва избора на файлове от страницата „Торенти“. „Собствен“ го заменя за тази категория, например за музикална категория, в която малките файлове са самият албум. Прилага се при старта на торента, затова обхваща и торент, който правило на Packagizer подрежда тук. Файловете, които отметнеш сам, винаги печелят.',
