  'container.usenet': '{file} беше предаден на {service}. Файловете му ще се появят тук, щом {service} ги изтегли от Usenet.',
  'settings.help.intake.watchFiles': 'Наблюдавана папка поема каквото оставиш в нея: списъци с връзки (.txt, .crawljob, .magnet), .torrent файлове, контейнери (.dlc, .ccf, .rsdf) и .nzb файлове.',
  'container.nzbTooBig': 'по-голям е от {max}, а .nzb файл не може да бъде по-голям',
