  'activity.usenet': 'Usenet',
  'settings.help.intake.nzb':
    'An .nzb, uploaded here or sent by Sonarr or Radarr, goes to your TorBox or Premiumize.me account, which fetches it from Usenet. Its files then download like any other link. TorBox takes .nzb files only on plans that include Usenet. KnightLoader finds out when TorBox turns down the first one, and that .nzb fails unless a Premiumize.me account takes it.',
  'task.remote': 'Изтегля се при {service}',
  'task.remoteSeeds': 'Сийдове: {n}',
  'accounts.routing.orderHintTorrents': 'Magnet връзките и .torrent файловете отиват или към „Торент и магнит“, вградения клиент, или към debrid услуга, която приема торенти, в зависимост от това кое е по-нагоре в списъка.',
  'accounts.routing.tip.torrent': 'Вграденият торент клиент. Ако над този ред стои debrid услуга, която приема торенти, тя изтегля magnet връзките и .torrent файловете вместо него.',
  'settings.torrents.debridTitle': 'Чрез debrid услуга',
  'settings.torrents.debridHint': 'TorBox, Real-Debrid, AllDebrid, Premiumize.me и Debrid-Link могат да изтеглят magnet връзки и .torrent файлове вместо вградения клиент. Услугата изтегля торента на собствените си сървъри, а KnightLoader после изтегля файловете оттам като всяка друга връзка. От тази машина нищо не се сийдва и адресът ти никога не се появява в рой, така че не е нужно да има отворен порт. Торент, който услугата вече има, е готов веднага. Редът на приоритет на страницата „Акаунти“ решава кое е първо: debrid услуга или вграденият клиент. Торент от частен тракер винаги остава при вградения клиент. Изборът на файлове на тази страница избира файловете и тук: Real-Debrid и Debrid-Link изтеглят само тях, а от другите услуги тук идват само те.',
  'accounts.col.import': 'Внасяне',
  'task.remoteHint': '{service} изтегля това на собствените си сървъри и засега има {percent}. Файловете идват тук, щом ги има всички.',
  'settings.modules.detail.torrentsOffDebrid': 'Изключен. Текущите торенти продължават да вървят и да сийдват. Новите отиват към debrid услуга, която приема торенти.',
  'collector.filtered.origin.account': 'debrid акаунт',
  'accounts.importAccount': 'Внасяне от {account}',
  'accounts.importHint': 'KnightLoader чете списъка на услугата веднъж в минута и внася всичко, добавено там, откакто това е включено: торенти, а от TorBox и Premiumize.me и уеб и Usenet изтегляния. Те попадат в събирача на връзки като всяка друга връзка и се изтеглят от този акаунт. Нищо, което KnightLoader е добавил сам, не влиза тук. Услугата не казва кой е добавил дадено изтегляне, затова влиза и всичко, което друго приложение добави със същия акаунт. Остави това изключено за акаунт, който използва и rdt-client или втори KnightLoader. Щом файловете на изтеглянето са тук или когато премахнеш изтеглянето тук, то се изтрива в услугата, освен ако в Настройки, Торенти не е зададено изтеглянията да остават там. Тире означава, че услугата няма списък, който KnightLoader може да прочете.',
  'settings.torrents.keepOnService': 'Запазвай изтеглянията в debrid услугата',
  'settings.torrents.keepOnServiceHint': 'Когато е изключено, KnightLoader изтрива торента от debrid услугата, щом всичките му файлове са тук, и прави същото с изтегляне, внесено от акаунта, за да не се трупа нищо там за сметка на лимитите на акаунта. Внесено изтегляне, което премахнеш тук, преди да е завършило, се изтрива и там. Когато е включено, и двете остават в услугата, например за да можеш по-късно да ги стриймваш оттам. Торент, добавен от KnightLoader, се изтрива във всеки случай, ако го премахнеш, преди да е завършил, а такъв, който акаунтът вече е имал, никога не се изтрива.',
